+function EmptySection(props: { readonly section: BrowserSection }): JSX.Element {
+  return (
+    <p style={{ padding: 'var(--arq-space-panel)', color: 'var(--arq-ui-text-muted)', margin: 0 }}>
+      Nothing here yet. {BROWSER_SECTION_PURPOSE[props.section]}.
+    </p>
+  );
